type InputTask = {
  id: string;
  duration: number;
  dependsOn?: string[];
};

type Task = {
  id: string;
  duration: number;
  dependsOn: string[];
};

function fail(message: string): never {
  console.error(`Error: ${message}`);
  process.exit(1);
}

function validate(value: unknown): Task[] {
  if (typeof value !== "object" || value === null || !Array.isArray((value as { tasks?: unknown }).tasks)) {
    fail("input must be an object with a tasks array");
  }

  const rawTasks = (value as { tasks: unknown[] }).tasks;
  const tasks: Task[] = [];
  const ids = new Set<string>();

  for (const [index, raw] of rawTasks.entries()) {
    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
      fail(`tasks[${index}] must be an object`);
    }
    const task = raw as Partial<InputTask>;
    if (typeof task.id !== "string" || task.id.length === 0) fail(`tasks[${index}].id must be a non-empty string`);
    if (ids.has(task.id)) fail(`duplicate task id: ${task.id}`);
    if (typeof task.duration !== "number" || !Number.isFinite(task.duration) || task.duration < 0) {
      fail(`tasks[${index}].duration must be a finite non-negative number`);
    }
    const dependsOn = task.dependsOn ?? [];
    if (!Array.isArray(dependsOn) || dependsOn.some((id) => typeof id !== "string")) {
      fail(`tasks[${index}].dependsOn must be an array of strings`);
    }
    if (new Set(dependsOn).size !== dependsOn.length) fail(`tasks[${index}].dependsOn contains duplicate ids`);
    if (dependsOn.includes(task.id)) fail(`task ${task.id} cannot depend on itself`);
    ids.add(task.id);
    tasks.push({ id: task.id, duration: task.duration, dependsOn });
  }

  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (!ids.has(dependency)) fail(`task ${task.id} depends on unknown task: ${dependency}`);
    }
  }
  return tasks;
}

function findCycle(tasks: Task[], byId: Map<string, Task>): string[] | undefined {
  const state = new Map<string, number>();
  const path: string[] = [];
  const visit = (id: string): string[] | undefined => {
    state.set(id, 1);
    path.push(id);
    for (const dependency of [...byId.get(id)!.dependsOn].sort()) {
      if (state.get(dependency) === 1) return [...path.slice(path.indexOf(dependency)), dependency];
      if (!state.has(dependency)) {
        const cycle = visit(dependency);
        if (cycle) return cycle;
      }
    }
    path.pop();
    state.set(id, 2);
  };
  for (const task of [...tasks].sort((a, b) => a.id.localeCompare(b.id))) {
    if (!state.has(task.id)) {
      const cycle = visit(task.id);
      if (cycle) return cycle;
    }
  }
}

function plan(tasks: Task[]) {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const cycle = findCycle(tasks, byId);
  if (cycle) fail(`dependency cycle: ${cycle.join(" -> ")}`);

  const children = new Map(tasks.map((task) => [task.id, [] as string[]]));
  const remaining = new Map(tasks.map((task) => [task.id, task.dependsOn.length]));
  for (const task of tasks) for (const dependency of task.dependsOn) children.get(dependency)!.push(task.id);
  for (const childIds of children.values()) childIds.sort();

  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
  const order: string[] = [];
  while (ready.length > 0) {
    const id = ready.shift()!;
    order.push(id);
    for (const child of children.get(id)!) {
      const count = remaining.get(child)! - 1;
      remaining.set(child, count);
      if (count === 0) {
        ready.push(child);
        ready.sort();
      }
    }
  }

  const earliest: Record<string, { start: number; finish: number }> = {};
  const paths = new Map<string, string[]>();
  const layers: string[][] = [];
  for (const id of order) {
    const task = byId.get(id)!;
    let start = 0;
    let predecessor: string | undefined;
    for (const dependency of task.dependsOn) {
      const finish = earliest[dependency].finish;
      if (finish > start || (finish === start && predecessor !== undefined && dependency.localeCompare(predecessor) < 0)) {
        start = finish;
        predecessor = dependency;
      }
    }
    earliest[id] = { start, finish: start + task.duration };
    const layer = task.dependsOn.length === 0 ? 0 : Math.max(...task.dependsOn.map((dependency) => layers.findIndex((group) => group.includes(dependency)) + 1));
    (layers[layer] ??= []).push(id);
    paths.set(id, predecessor ? [...paths.get(predecessor)!, id] : [id]);
  }
  for (const layer of layers) layer.sort();

  const totalDuration = Math.max(0, ...Object.values(earliest).map(({ finish }) => finish));
  const candidates = order.filter((id) => earliest[id].finish === totalDuration).map((id) => paths.get(id)!);
  candidates.sort((a, b) => a.join("\u0000").localeCompare(b.join("\u0000")));
  return { order, layers, earliest, totalDuration, criticalPath: candidates[0] ?? [] };
}

const args = process.argv.slice(2);
if (args.length !== 2 || args[0] !== "plan" || args[1].startsWith("-")) fail("usage: bun run src/cli.ts plan INPUT.json");
let input: unknown;
try {
  input = JSON.parse(await Bun.file(args[1]).text());
} catch (error) {
  fail(`cannot read valid JSON from ${args[1]}: ${error instanceof Error ? error.message : String(error)}`);
}
console.log(JSON.stringify(plan(validate(input))));
